// Đồng bộ NGƯỢC: đọc Postgres (Neon) rồi ghi đè các file nội dung tĩnh trong
// src/content/set18/*.ts + src/content/patch-notes.generated.ts. Đây là bước
// "ghi đè" sau khi sửa dữ liệu trong DB (qua apply-patch-draft.ts hoặc UPDATE
// trực tiếp) — chạy xong thì `git diff` để duyệt trước khi commit/deploy, giữ
// đúng quy trình review đã dùng từ trước khi có DB.
//
// Chạy: pnpm db:pull
// Check generated files without writing: pnpm db:pull:check

import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { neon } from '@neondatabase/serverless';
import { asc } from 'drizzle-orm';
import { db } from '../../src/db/client';
import {
  set18Champions,
  set18Traits,
  set18Augments,
  set18Wisps,
  set18Items,
  patchReports as patchReportsTable,
  patchEntries as patchEntriesTable,
} from '../../src/db/schema';
import { buildSet18Slugs, buildSet18SlugsSource, writeSet18Slugs } from './lib/build-set18-slugs';
import { validateGeneratedSet18ChampionHtml } from '../lib/trusted-html-validation.mjs';

// `tsx`/Node can consume dash-prefixed runtime flags before this script sees
// them. Package scripts use the plain `check` token; keep `--check` for direct
// runtimes that pass it through.
const CHECK_MODE = process.argv.includes('check') || process.argv.includes('--check');
const staleFiles: string[] = [];

type ColumnExistsRow = { exists: boolean };
type TipRow = {
  id: string;
  slug: string;
  title_vi: string;
  content_vi: string;
  entity_ids?: string[] | null;
  champion_ids: string[];
  trait_ids: string[];
  source_url: string | null;
};

function normalizeLineEndings(value: string) {
  return value.replace(/\r\n/g, '\n');
}

function omitKeys<T extends Record<string, unknown>>(obj: T, keys: (keyof T)[]): T {
  const copy = { ...obj };
  for (const k of keys) delete copy[k];
  return copy;
}

/** Xoá field optional (kiểu `foo?: X`, KHÔNG phải `foo: X | null`) khi giá trị
 * là null — gán thẳng null vào field optional sẽ vỡ type (X | undefined, không
 * nhận null). Field nullable thật sự (vd Set18Wisp.cost: number | null) không
 * được liệt vào đây, phải giữ nguyên null. */
function stripNullOptionals<T extends Record<string, unknown>>(obj: T, optionalKeys: (keyof T)[]): T {
  const copy = { ...obj };
  for (const k of optionalKeys) {
    if (copy[k] === null) delete copy[k];
  }
  return copy;
}

function writeOutput(path: string, content: string) {
  if (CHECK_MODE) {
    const current = existsSync(path) ? readFileSync(path, 'utf8') : '';
    if (normalizeLineEndings(current) !== normalizeLineEndings(content)) staleFiles.push(path);
    return;
  }
  writeFileSync(path, content);
}

function writeGenerated(path: string, header: string[], exportLines: string | string[]) {
  const lines = Array.isArray(exportLines) ? exportLines : [exportLines];
  writeOutput(path, [...header, '', ...lines, ''].join('\n'));
}

async function pullChampions() {
  const rows = await db
    .select()
    .from(set18Champions)
    .orderBy(asc(set18Champions.cost), asc(set18Champions.name));
  const data = rows.map((r) => stripNullOptionals(omitKeys(r, ['id', 'updatedAt']), ['forms', 'nicknameVi']));
  validateGeneratedSet18ChampionHtml(data, 'set18_champions');
  writeGenerated(
    'src/content/set18/set18-champions.ts',
    ['// GENERATED FILE — do not edit by hand.', '// Generated by Website/scripts/db/pull-set18.ts từ bảng set18_champions trên Neon.', '', "import type { Set18Champion } from './set18-types';"],
    [
      `export const set18Champions: Set18Champion[] = ${JSON.stringify(data)};`,
      'export const set18ChampionByName = new Map(set18Champions.map((champion) => [champion.name, champion]));',
    ],
  );
  console.log(`✓ set18-champions.ts: ${data.length} dòng`);
  return rows;
}

async function pullTraits() {
  const rows = await db.select().from(set18Traits).orderBy(asc(set18Traits.name));
  const data = rows.map((r) =>
    stripNullOptionals(omitKeys(r, ['id', 'updatedAt']), ['infoChips', 'bounties', 'subEffects', 'note', 'activation', 'wide']),
  );
  writeGenerated(
    'src/content/set18/set18-traits.ts',
    ['// GENERATED FILE — do not edit by hand.', '// Generated by Website/scripts/db/pull-set18.ts từ bảng set18_traits trên Neon.', '', "import type { Set18Trait, Set18TraitType } from './set18-types';"],
    [
      `export const set18Traits: Set18Trait[] = ${JSON.stringify(data)};`,
      'export const set18TraitByName = new Map(set18Traits.map((trait) => [trait.name, trait]));',
      'export const set18TraitsByType = (type: Set18TraitType) => set18Traits.filter((trait) => trait.type === type);',
    ],
  );
  console.log(`✓ set18-traits.ts: ${data.length} dòng`);
  return rows;
}

